function formatPrice(cents: number) {
  return (cents / 100).toFixed(2);
}

function display(item: Item) {
  const price = formatPrice(item.priceCents);
  console.log(item.name + " costs $" + price);
}

// Version A: inline calculation
function checkout(items: Item[], discountRate: number) {
  const total = items.reduce((sum, item) => {
    const discounted = item.price * (1 - discountRate);
    return sum + discounted;
  }, 0);
  return total;
}

// Version B: extracted helper
function applyDiscount(price: number, rate: number) {
  return price * (1 - rate);
}
function checkout2(items: Item[], discountRate: number) {
  const total = items.reduce((sum, item) => sum + applyDiscount(item.price, discountRate), 0);
  return total;
}
